 fn enter(cx:&StepContext<'_>,demand:RetirementDemand,items:usize)->bool{!cx.should_yield()&&!cx.is_cancelled()&&cx.retained_grant().maximum_items>=items&&cx.retained_work_can_enter(demand)}
