  let demand=self.drawing_demand(address)?;if !Self::enter(cx,demand,2){return Ok(false)}let owners=self.owners.original_mut().ok_or_else(||invalid("export original sources are closing"))?;
  if owners.parent.is_none(){if owners.original.is_none(){Self::consume(cx,demand,0)?;let Some(original)=input.snapshot_read.take_current(input.operation.generation,input.operation.canonical_base_revision,cx)?else{return Ok(false)};owners.original=Some(original);return Ok(false)}let original=owners.original.take().unwrap();match original.admit_retained_clone_source(cx.retained_grant()){Ok((source,p))=>{owners.parent=Some(source);cx.consume_retained(p)?;cx.consume_fuel(1)},Err((error,original))=>{owners.original=Some(original);cx.consume_retained(error.retained_progress())?;return Err(error.into())}}return Ok(false)}
