 fn receive_original_output_chunks(&mut self,chunks:&mut Option<ArtifactOutputChunks>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let owners=self.owners.original_mut().ok_or_else(||invalid("export original output receiver is closing"))?;if self.output_received{if chunks.is_some(){return Err(invalid("export original output queue was replaced after transfer").into())}return Ok(true)}let demand=Self::transition::<ArtifactOutputChunks>();if !Self::enter(cx,demand,1){return Ok(false)}if chunks.is_none(){return Err(invalid("export actual supplied output queue is absent").into())}owners.chunks=chunks.take();self.output_received=true;Self::consume(cx,demand,0)?;Ok(true)}
