   let supplier=input.snapshot_owner.ok_or_else(||invalid("export original snapshot supplier is absent"))?;if !std::ptr::eq(supplier.as_ref(),input.snapshot){return Err(invalid("export original snapshot supplier differs from actual input").into())}let metadata=owners.metadata.as_mut().unwrap();let chunks=owners.chunks.take().ok_or_else(||invalid("export original output roots disappeared before core birth"))?;let request=LayoutExportRequest{kind:self.kind,page_id:metadata.page_id.take(),snapshot:Arc::clone(supplier),preflight_json:None,parent_document_id:std::mem::take(&mut metadata.parent_document_id),canonical_base_revision_hex:std::mem::take(&mut metadata.canonical_base_revision_hex)};self.inner=Some(LayoutExportJob::from_admitted(self.operation,(cx.operation(),cx.generation()),request,chunks));Self::consume(cx,demand,0)?;return Ok(Self::pending())
