 fn reports_progress(&self)->bool{true}
 fn begin_close(&mut self){self.closing=true;if let Some(inner)=self.inner.as_mut(){inner.begin_close()}if let Some(metadata)=self.metadata.as_mut(){metadata.begin_close()}}
